            raise ValueError(
                "checkpoint candidate cost does not match its path"
            )
        if max_cost is not None and g > max_cost:
            raise ValueError(
                "checkpoint candidate cost exceeds the cost limit"
            )

    best = {}
    for cell, g, path in best_entries:
        check_route(path, g)
