    raw_open = raw["open"]
    if isinstance(raw_open, (str, bytes)) or not isinstance(raw_open, Sequence):
        raise TypeError(
            f"checkpoint state open must be a sequence of candidates, "
            f"got {type(raw_open).__name__}"
