        state = _restore_tree_state(
            checkpoint["state"], planner, dynamic, width, height,
            obstacles, frames, start, goal, goals, costs, closed_count,
            trace, max_cost, allow_wait
        )
    return {
        "planner": planner,
        "width": width,
        "height": height,
        "obstacles": obstacles,
        "start": start,
        "starts": starts,
        "goal": goal,
        "goals": goals,
        "costs": costs,
        "frames": frames,
        "max_cost": max_cost,
        "allow_wait": allow_wait,
        "state": state,
    }


